details.returned_prompt:
{
  "high_level_description": "A documentary photograph of a working wood-fired grill in an open restaurant kitchen during the quiet lull between lunch and dinner service, with a sea bream and blistering vegetables on the grate, herbs hanging above, and a soft-focus kitchen receding behind. Shot on Kodak Portra with fine grain.",
  "compositional_deconstruction": {
    "background": "Open restaurant kitchen interior in cool-neutral daylight spilling from an off-frame window on the left, white balance neutral overall with the amber pool of light local only to the embers and underside of the food. A brick hearth wall forms the backdrop behind the grill, weathered red-brown bricks with mortar lines visible. The ceiling above is dim and out of focus. Mild atmospheric haze from rising smoke catches the daylight as it drifts upward. Fine Kodak Portra grain throughout.",
    "elements": [
      {
        "type": "obj",
        "desc": "Back shelf deep in the background, slightly out of focus, holding a stainless steel saucepan on the left and a polished copper kettle on the right, both catching faint daylight highlights."
      },
      {
        "type": "obj",
        "desc": "Horizontal iron rail mounted across the upper third of the frame above the hearth, dark matte finish. Bunches of fresh herbs — rosemary sprigs, thyme stems, oregano, bay leaves — tied with natural twine hang from the rail at intervals, gently softened by shallow depth of field."
      },
      {
        "type": "obj",
        "desc": "Long rectangular wood-fired grill built into a brick hearth, spanning most of the frame width across the lower two-thirds. Heavy cast-iron grate sits atop glowing orange embers and a bed of pale grey ash beneath. Brick surround visible along the sides and back."
      },
      {
        "type": "obj",
        "desc": "Thin curl of pale grey smoke rising from the embers through gaps in the grate, dissipating upward toward the ceiling, catching the cool daylight as it drifts."
      },
      {
        "type": "obj",
        "desc": "Whole sea bream laid skin-side down on the cast-iron grate, centered slightly left. Charred grill marks streak across the flesh side, scales intact on the visible belly edge. A lemon half tucked under the tail, cut face up, juice glistening."
      },
      {
        "type": "obj",
        "desc": "Three red bell peppers blistering on the grate to the right of the fish, skins splitting and blackening at the edges, charred patches against bright red flesh, juices pooling where they rest on the iron."
      },
      {
        "type": "obj",
        "desc": "Two courgettes halved lengthwise laid cut-side down on the grate beside the peppers, edges caramelizing to deep brown, pale green flesh visible at the rounded outer sides."
      },
      {
        "type": "obj",
        "desc": "Stack of four well-seasoned cast-iron pans leaning against the brick hearth to the right of the grill, dark patina with faint oil sheen catching daylight, rims stacked unevenly, handles protruding outward."
      },
      {
        "type": "obj",
        "desc": "Out-of-focus wooden prep counter slicing in from the lower-left foreground edge, warm honey-toned grain softened by shallow depth of field. A small pile of coarse white salt mounded near the center, a folded cream linen cloth resting beside it."
      }
    ]
  }
}
